def min_max_drying_time(h, w, n, pattern, commands):
    directions = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}
    def is_valid(x, y):
        return 0 <= x < h and 0 <= y < w

    def simulate(commands, start_x, start_y):
        x, y = start_x, start_y
        visited = [[False] * w for _ in range(h)]
        stack = [(x, y, 0)]
        while stack:
            x, y, t = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            if pattern[x][y] == '#' and t % 2 == 0:
                return False
            elif pattern[x][y] == '.' and t % 2 == 1:
                return False
            for dx, dy in directions.values():
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny):
                    stack.append((nx, ny, t + 1))
        return True

    min_t = float('inf')
    max_t = -1
    for i in range(n):
        direction, distance = commands[i].split()
        dx, dy = directions[direction]
        for dist in range(1, distance + 1):
            new_x, new_y = i // w + dist * dx, i % w + dist * dy
            if is_valid(new_x, new_y):
                if simulate(commands[:i+1], new_x, new_y):
                    min_t = min(min_t, i + dist)
                    max_t = max(max_t, i + dist)

    return min_t if min_t != float('inf') else -1, max_t

