def simulate(h, w, n, pattern, commands):
    directions = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}
    grid = [[False] * w for _ in range(h)]
    x, y = h - 1, 0

    def is_valid(x, y):
        return 0 <= x < h and 0 <= y < w

    def mark(x, y, t):
        if is_valid(x, y) and not grid[x][y]:
            grid[x][y] = True
            return t
        return -1

    def unmark(x, y):
        if is_valid(x, y) and grid[x][y]:
            grid[x][y] = False

    min_time = float('inf')
    max_time = -1

    for i in range(n):
        dir, dist = commands[i].split()
        dx, dy = directions[dir]
        for j in range(1, int(dist) + 1):
            nx, ny = x + dx * j, y + dy * j
            if is_valid(nx, ny):
                if pattern[nx][ny] == '#':
                    min_time = min(min_time, mark(nx, ny, i * int(dist) + j))
                else:
                    unmark(nx, ny)

    if not any(grid[x][y] for x in range(h) for y in range(w)):
        return -1, -1

    for i in range(n - 1, -1, -1):
        dir, dist = commands[i].split()
        dx, dy = directions[dir]
        for j in range(int(dist), 0, -1):
            nx, ny = x + dx * j, y + dy * j
            if is_valid(nx, ny):
                if pattern[nx][ny] == '.':
                    max_time = max(max_time, i * int(dist) + j)
                else:
                    break

    return min_time, max_time

