    directions = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}
    grid = [[False] * w for _ in range(h)]
    x, y = h - 1, 0

    def is_valid(x, y):
        return 0 <= x < h and 0 <= y < w

    def mark(x, y, t):
        if is_valid(x, y) and not grid[x][y]:
            grid[x][y] = True
            return t
        return -1

    def unmark(x, y):
        if is_valid(x, y) and grid[x][y]:
            grid[x][y] = False

    for i, cmd in enumerate(commands):
        dir, dist = cmd.split()
        dx, dy = directions[dir]
        for _ in range(int(dist)):
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                if mark(nx, ny, i) == -1:
                    break
                x, y = nx, ny
            else:
                break

    min_time = float('inf')
    max_time = -1

    def dfs(x, y, t):
        nonlocal min_time, max_time
        if t >= min_time:
            return
        if t > max_time:
            max_time = t

        for dx, dy in directions.values():
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and grid[nx][ny]:
                dfs(nx, ny, t + 1)

    dfs(x, y, 0)

    if min_time == float('inf'):
        return -1, -1

    return min_time, max_time

